import{_ as r,o as e,c as a,a5 as d}from"./chunks/framework.D_J2JZBr.js";const b=JSON.parse('{"title":"友链与资源入口","description":"精选学生 Wiki、上科大官方入口、开放课程与芯片开源社区，按需求寻找下一步资源。","frontmatter":{"title":"友链与资源入口","description":"精选学生 Wiki、上科大官方入口、开放课程与芯片开源社区，按需求寻找下一步资源。"},"headers":[],"relativePath":"tools/links.md","filePath":"tools/links.md","lastUpdated":1795531638000}'),h={name:"tools/links.md"};function i(n,t,o,s,l,c){return e(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="友链与资源入口" tabindex="-1">友链与资源入口 <a class="header-anchor" href="#友链与资源入口" aria-label="Permalink to &quot;友链与资源入口&quot;">​</a></h1><p>这里收录值得长期保留的入口，而不是尽可能多的链接。建议先确定一个问题，再选一门课程或一个项目深入；收藏数量不会自动变成能力。外站的课程版本、许可证和访问条件由原维护者决定，本站收录不代表合作关系或内容背书。</p><h2 id="学生-wiki-与自学指南" tabindex="-1">学生 Wiki 与自学指南 <a class="header-anchor" href="#学生-wiki-与自学指南" aria-label="Permalink to &quot;学生 Wiki 与自学指南&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>适合什么需求</th><th>使用提醒</th></tr></thead><tbody><tr><td><a href="https://njuic-students.github.io/" target="_blank" rel="noreferrer">NJU 集成全家桶</a></td><td>看集成电路学生 Wiki 如何组织课程、科研和成长经验</td><td>面向南京大学的校内信息不能直接套用到上科大</td></tr><tr><td><a href="https://crys-chen.github.io/ic-guide/" target="_blank" rel="noreferrer">IC 自学指南</a></td><td>按知识地图和科研方向选择公开课程</td><td>用于补充知识，上科大培养要求仍看本校文件</td></tr><tr><td><a href="https://csdiy.wiki/" target="_blank" rel="noreferrer">CS 自学指南</a></td><td>补编程、算法、体系结构、操作系统等计算机基础</td><td>原项目由 pkuflyingpig 发起；按先修与自己的节奏选择</td></tr><tr><td><a href="https://github.com/pkuflyingpig/cs-self-learning" target="_blank" rel="noreferrer">CS 自学指南源仓库</a></td><td>查看更新、参与贡献与核对项目说明</td><td>转载和修改先看相应许可</td></tr><tr><td><a href="https://qsctech.github.io/zju-icicles/" target="_blank" rel="noreferrer">浙江大学课程攻略共享计划</a></td><td>了解课程资源组织方式与同类经验共享项目</td><td>不照搬外校课程评价，使用资料需遵守版权和课程规则</td></tr><tr><td><a href="https://zju-turing.github.io/TuringCourses/" target="_blank" rel="noreferrer">浙江大学图灵班学习指南</a></td><td>了解计算机与系统课程的学习背景</td><td>是学生指南，不等于官方教学平台；尊重其独立内容许可</td></tr></tbody></table><p>本站的缘起与定位见<a href="/shanghaitech-ic-wiki-dev.github.io/community/">关于本站</a>。这些项目给我们的启发是把信息连成路径，而不是复制内容或代替独立学习。</p><h2 id="上科大与相关培养机构" tabindex="-1">上科大与相关培养机构 <a class="header-anchor" href="#上科大与相关培养机构" aria-label="Permalink to &quot;上科大与相关培养机构&quot;">​</a></h2><table tabindex="0"><thead><tr><th>入口</th><th>主要用途</th></tr></thead><tbody><tr><td><a href="https://www.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">上海科技大学</a></td><td>学校新闻、组织与官方服务入口</td></tr><tr><td><a href="https://sist.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">信息科学与技术学院</a></td><td>师资、招生、讲座、实习就业及学院通知</td></tr><tr><td><a href="https://sist.shanghaitech.edu.cn/szdwx/list.htm" target="_blank" rel="noreferrer">信息学院师资队伍</a></td><td>核对教授职称、研究中心与公开主页</td></tr><tr><td><a href="https://vsplab.cn/" target="_blank" rel="noreferrer">VSPLab</a></td><td>了解 VLSI 信号处理实验室的公开研究与信息</td></tr><tr><td><a href="https://www.sisi.edu.cn/" target="_blank" rel="noreferrer">上海创芯学院</a></td><td>查询学院公开介绍、新闻与培养信息</td></tr><tr><td><a href="https://yanzhao.shanghaitech.edu.cn/" target="_blank" rel="noreferrer">上科大研究生招生网</a></td><td>核对年度招生简章、专业目录与录取流程</td></tr><tr><td><a href="https://sist.shanghaitech.edu.cn/2844/list.htm" target="_blank" rel="noreferrer">信息学院实习信息</a></td><td>查找公开实习线索，注意发布日期与有效性</td></tr></tbody></table><p>站内已整理<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/faculty/">教授与课题组</a>、<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/research-groups/">平台资源</a>和<a href="/shanghaitech-ic-wiki-dev.github.io/shanghaitech/programs">培养项目</a>，适合先建立框架，再回官方页面核对最新版本。</p><h2 id="芯片开源生态与练习" tabindex="-1">芯片开源生态与练习 <a class="header-anchor" href="#芯片开源生态与练习" aria-label="Permalink to &quot;芯片开源生态与练习&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>适合什么需求</th></tr></thead><tbody><tr><td><a href="https://ysyx.oscc.cc/" target="_blank" rel="noreferrer">一生一芯</a></td><td>从数字逻辑、编程和处理器走向软硬件系统实践</td></tr><tr><td><a href="https://ysyx.oscc.cc/docs/" target="_blank" rel="noreferrer">一生一芯官方讲义</a></td><td>核对当前课程版本、阶段和任务，避免混用旧路线</td></tr><tr><td><a href="https://theopenroadproject.org/" target="_blank" rel="noreferrer">OpenROAD</a></td><td>了解开源数字芯片物理实现流程</td></tr><tr><td><a href="https://www.chipsalliance.org/" target="_blank" rel="noreferrer">CHIPS Alliance</a></td><td>查找开放硬件与相关软件工具生态</td></tr><tr><td><a href="https://riscv.org/" target="_blank" rel="noreferrer">RISC-V International</a></td><td>进入开放指令集规范与官方生态信息</td></tr><tr><td><a href="https://hdlbits.01xz.net/" target="_blank" rel="noreferrer">HDLBits</a></td><td>通过小题练习 Verilog 与数字逻辑</td></tr><tr><td><a href="https://yosyshq.net/yosys/" target="_blank" rel="noreferrer">Yosys</a></td><td>学习开源逻辑综合工具</td></tr><tr><td><a href="https://www.veripool.org/verilator/" target="_blank" rel="noreferrer">Verilator</a></td><td>了解 RTL 仿真与模型编译工具</td></tr></tbody></table><p>开源工具不意味着工艺资料都可公开，开源项目也各有许可证。运行公开 RTL、实现版图和真正完成流片是不同层次，不能相互替代作为能力证明。实操路线见<a href="/shanghaitech-ic-wiki-dev.github.io/tools/open-source/">开源 EDA</a>与<a href="/shanghaitech-ic-wiki-dev.github.io/competitions/projects/ysyx">一生一芯介绍</a>。</p><h2 id="公开课程与实验平台" tabindex="-1">公开课程与实验平台 <a class="header-anchor" href="#公开课程与实验平台" aria-label="Permalink to &quot;公开课程与实验平台&quot;">​</a></h2><table tabindex="0"><thead><tr><th>资源</th><th>可学习的内容</th><th>访问与使用提醒</th></tr></thead><tbody><tr><td><a href="https://lab.cs.tsinghua.edu.cn/" target="_blank" rel="noreferrer">清华大学计算机国家级实验教学中心</a></td><td>数字逻辑、组成原理等实验平台与教学信息</td><td>文档公开不代表远程硬件或评测账号向校外开放</td></tr><tr><td><a href="https://nju-projectn.github.io/ics-pa/" target="_blank" rel="noreferrer">南京大学计算机系统基础实验（ICS PA）</a></td><td>通过模拟器和运行时理解程序与系统</td><td>按课程版本阅读，不以抄现成解答替代实现</td></tr><tr><td><a href="https://www.nand2tetris.org/" target="_blank" rel="noreferrer">Nand2Tetris</a></td><td>从逻辑门到完整计算机的基础路线</td><td>可作系统入门，不等同于工业芯片设计流程</td></tr><tr><td><a href="https://ocw.mit.edu/" target="_blank" rel="noreferrer">MIT OpenCourseWare</a></td><td>数学、物理、电子与计算机公开课程</td><td>根据先修选内容，注意教材与视频版本</td></tr><tr><td><a href="https://cs61c.org/" target="_blank" rel="noreferrer">Berkeley CS61C</a></td><td>计算机组成、RISC-V 与系统基础</td><td>实验平台与自动评测政策按当期规定</td></tr></tbody></table><p>如果发现失效链接，欢迎通过<a href="/shanghaitech-ic-wiki-dev.github.io/community/contributing">参与共建</a>附上原链接、问题和可靠替代入口。推荐新资源时，请说明适合人群、先修要求以及它能解决什么问题；优先官网和维护稳定的项目，不收录盗版教材、破解工具或泄露课程答案。</p>',14)])])}const g=r(h,[["render",i]]);export{b as __pageData,g as default};
